import { randomUUID } from "node:crypto";
import { cancelOrder, createOrder, Order, OrderItem, OrderState, transitionOrder } from "../domain/order";
import { CatalogueProduct, DomainError, Product } from "../domain/product";

export class NotFoundError extends Error {
  public constructor(message: string) { super(message); this.name = "NotFoundError"; }
}

export class InsufficientStockError extends Error {
  public constructor(productId: string) {
    super(`Insufficient stock for product ${productId}`);
    this.name = "InsufficientStockError";
  }
}

export interface FulfilmentStore {
  findProduct(id: string): Product | undefined;
  saveProduct(product: Product): void;
  listProducts(): Product[];
  findOrder(id: string): Order | undefined;
  saveOrder(order: Order): void;
  listOrders(state?: OrderState): Order[];
}

export class OrderService {
  public constructor(private readonly store: FulfilmentStore) {}

  public addProduct(id: string, name: string, stock: number): Product {
    if (this.store.findProduct(id)) throw new DomainError(`Product ${id} already exists`);
    const product = { id, name, stock };
    if (!id.trim() || !name.trim() || !Number.isSafeInteger(stock) || stock < 0) {
      throw new DomainError("Product requires an id, name, and non-negative integer stock");
    }
    this.store.saveProduct(product);
    return cloneProduct(product);
  }

  public listProducts(): CatalogueProduct[] { return this.store.listProducts().map(cloneProduct); }

  public placeOrder(items: OrderItem[]): Order {
    const order = createOrder(randomUUID(), items);
    const products = order.items.map((item) => ({ item, product: this.requireProduct(item.productId) }));
    for (const { item, product } of products) {
      if (product.stock < item.quantity) throw new InsufficientStockError(item.productId);
    }
    for (const { item, product } of products) {
      product.stock -= item.quantity;
      this.store.saveProduct(product);
    }
    this.store.saveOrder(order);
    return cloneOrder(order);
  }

  public getOrder(id: string): Order { return cloneOrder(this.requireOrder(id)); }

  public listOrders(state?: OrderState): Order[] { return this.store.listOrders(state).map(cloneOrder); }

  public transitionOrder(id: string, state: OrderState): Order {
    const order = this.requireOrder(id);
    transitionOrder(order, state);
    this.store.saveOrder(order);
    return cloneOrder(order);
  }

  public cancelOrder(id: string): Order {
    const order = this.requireOrder(id);
    cancelOrder(order);
    for (const item of order.items) {
      const product = this.requireProduct(item.productId);
      product.stock += item.quantity;
      this.store.saveProduct(product);
    }
    this.store.saveOrder(order);
    return cloneOrder(order);
  }

  private requireProduct(id: string): Product {
    const product = this.store.findProduct(id);
    if (!product) throw new NotFoundError(`Product ${id} was not found`);
    return product;
  }

  private requireOrder(id: string): Order {
    const order = this.store.findOrder(id);
    if (!order) throw new NotFoundError(`Order ${id} was not found`);
    return order;
  }
}

function cloneProduct(product: Product): Product { return { ...product }; }
function cloneOrder(order: Order): Order { return { ...order, items: order.items.map((item) => ({ ...item })) }; }

